// Monitor honesty index — record JAH-GPCS-STUDIOMONITORS-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"watts": 100, "freq_range_khz": 19, "price_usd": 300};
var value = (m.watts*m.freq_range_khz/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-STUDIOMONITORS-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-STUDIOMONITORS-000001|' + value.toFixed(2) + ' honesty index');

